argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
Push-Location $repo;
$head=([string](git rev-parse HEAD)).Trim();
$dirty=@(git status --porcelain);
Pop-Location;
$cut='E:\WebAIBridge\app\data\projects-live-control-plane-cutover-r42.json';
if(!(Test-Path $cut)){ throw 'R42 cutover state missing after apply-03 effects' }
$state=Get-Content $cut -Raw|ConvertFrom-Json;
$manifest=[string]$state.rollbackManifest;
$manifestExists=Test-Path $manifest;
$m=$null;if($manifestExists){$m=Get-Content $manifest -Raw|ConvertFrom-Json}
[pscustomobject]@{
 head=$head;dirtyCount=$dirty.Count;
 cutoverStatus=$state.status;holdActive=$state.holdActive;
 rollbackManifest=$manifest;rollbackManifestExists=$manifestExists;
 rollbackCommand=[string]$state.rollbackCommand;
 preCutoverHead=if($m){[string]$m.preCutoverHead}else{''};
 backupRoot=if($m){[string]$m.backupRoot}else{''};
 targetSha=if($m){[string]$m.targetSha}else{''}
}|ConvertTo-Json -Depth 5 -Compress
